 $('pulse-hud').classList.add('hidden');$('revive-prompt').textContent=match.transition>0?match.notice:player.interaction?`${player.interaction.kind.toUpperCase()} · ${Math.ceil(player.interaction.time)}s · Stay near site`:match.mode==='snd'&&Math.hypot(player.x,player.z)<3?'E · PLANT / DEFUSE AT SITE A':'';$('down-notice').lastElementChild.textContent=match.mode==='tdm'?`Respawn in ${Math.max(0,Math.ceil(player.respawn||0))}s`:'Spectating · next round respawn';
