function restoreHostedWorld(w){
 if(!w?.run||!Array.isArray(w.players)||!Array.isArray(w.enemies))return;
 startOperation(w.level,true);match=w.match||null;runId=w.run;worldSequence=w.seq;score=w.score;kills=w.kills;pulseCharge=w.pulse||0;sessionDifficulty=w.difficulty||settings.difficulty;rules=levelRules(level,sessionDifficulty);rules.count+=Math.max(0,rooms.members.length-1)*2;rules.hp*=1+Math.max(0,rooms.members.length-1)*.2;
 for(const e of enemies)scene.remove(e.group);enemies.length=0;hitMeshes.length=0;for(const data of w.enemies){const e=createEnemy(data.x,data.z,data.id);Object.assign(e,{hp:data.hp,blind:data.blind,flash:data.flash});e.group.rotation.y=data.yaw;}pendingEnemies=w.pending||0;spawnSerial=w.spawnSerial||Math.max(-1,...w.enemies.map(e=>e.id))+1;
 for(const data of w.players){const p=data.id===rooms.memberId?player:squad.get(data.id);if(p)Object.assign(p,data,{ack:w.acks?.[data.id]||0});}for(const p of pickups)disposePickup(p);pickups.length=0;for(const p of w.pickups||[]){spawnPickup(p.x,p.z,p.type);pickups.at(-1).id=p.id;}
 for(const data of w.projectiles||[]){const mesh=new THREE.Mesh(data.type==='frag'?grenadeGeo:flashGeo,data.type==='frag'?grenadeMat:flashMat);scene.add(mesh);projectiles.push({...data,mesh});}events=w.events||[];eventSequence=Math.max(eventSequence,...events.map(e=>e.id));const loadout=w.hostLoadout;if(loadout){ammo=loadout.ammo;weapon=loadout.weapon;fragCount=loadout.fragCount;flashCount=loadout.flashCount;shots=loadout.shots;hits=loadout.hits;}rooms.hideLobby();updateHUD();if(w.phase==='result'){if(isPvp()){mode='playing';pvpTick(0);}else finish(!!w.win,true);}else{if(pendingEnemies===0&&!enemies.length)levelEnd=.8;pause();toast('ROOM RESTORED · Resume when you are ready');}
}
function guestEnemyTick(dt){const t=1-Math.exp(-16*dt);for(const e of enemies){e.x=THREE.MathUtils.lerp(e.x,e.targetX??e.x,t);e.z=THREE.MathUtils.lerp(e.z,e.targetZ??e.z,t);e.group.position.set(e.x,0,e.z);e.group.rotation.y=e.targetYaw||0;e.phase+=dt*6;e.legs[0].rotation.x=Math.sin(e.phase)*.3;e.legs[1].rotation.x=-e.legs[0].rotation.x;e.muzzle.visible=e.flash>0;e.blindMarker.visible=e.blind>0;}}

drawLevels();gun.visible=false;camera.position.set(28,20.5,33.2);camera.lookAt(-1,1,-3);renderer.compile(scene,camera);$('loading').classList.add('hidden');$('lobby').classList.remove('hidden');requestAnimationFrame(animate);
window.breachDiagnostics=()=>({mode,level,unlocked,hostiles:enemies.filter(e=>e.alive).length,pendingEnemies,health:Math.ceil(player.health),ammo:ammo[weapon],weapon:weapons[weapon].name,aiming:isAiming(),fov:camera.fov,fragCount,flashCount,projectiles:projectiles.length,blinded:enemies.filter(e=>e.blind>0).length,shots,hits,score,fps:fpsSample,drawCalls:renderer.info.render.calls,quality:settings.quality});

rooms.bind({getPlayer:localPose,getWorld:worldSnapshot,onInput:receiveInput,onWorld:receiveWorld,onMembers:syncMembers,onHostRestore:restoreHostedWorld,onHostStart:()=>{worldSequence=0;startOperation(selected,true);},onLobby:()=>{runId='';worldSequence=0;home();},onOpen:()=>releasePointer(),onLeave:()=>{runId='';home();},onNotice:toast});
